input.command:
firecrawl interact --timeout 280 --code '
const out=[];
for(let p=0;p<6;p++){await page.goto("https://www.databricks.com/customers?contentType=case+study&industry=1653&page="+p,{waitUntil:"networkidle"}); await page.waitForTimeout(2500);
const s=(await page.innerText("body")).match(/Showing [\d\-]+ of \d+/); 
const r=await page.$$eval("a[href*=\"/customers/\"]",as=>as.map(a=>a.href.split("?")[0]+" | "+a.innerText.replace(/\s+/g," ").trim().slice(0,100)));
out.push("#PAGE "+p+" "+(s&&s[0])); out.push(...r);}
console.log(out.join("\n"));' 2>&1 | grep -v "^Live\|^Interactive" > dbx-fs-raw.txt; grep "#PAGE" dbx-fs-raw.txt; grep -v "#PAGE\|Using scrape" dbx-fs-raw.txt | grep -v "| *$" | sort -u | wc -l

